 "correspondencia": "Mesmo ID Movnow no link de inscrição/hotsite, mesma data.", "observacao": "", "snapshot": {"estado": "PE", "data_final": "2027-09-04", "nome_evento": "Maratona Internacional de Pernambuco", "tipo_corrida": "rua", "ativo": true, "id_evento": 47365, "url_hotsite": "", "url_inscricao": "https://www.movnow.com.br/eventos/323-maratona-internacional-de-pernambuco", "tag": "2027-maratona-internacional-de-pernambuco", "cidade": "Recife", "data_inicial": "2027-09-04"}, "mensagem": "Pedido de vínculo da conta Movnow (25), registrado a pedido do administrador Leonardo Sobral (139) em 17/11/2026. Origem: conferência do catálogo público da Movnow; não representa aceite da ticketeira ou do organizador. Evento: Maratona Internacional de Pernambuco; 2027-09-04; Recife/PE. Fonte: https://www.movnow.com.br/eventos/323-maratona-internacional-de-pernambuco. Correspondência: Mesmo ID Movnow no link de inscrição/hotsite, mesma data. Manter PENDENTE até análise administrativa."}, {"movnow_id": 411, "movnow_nome": "Troca Trail", "data": "2027-11-28", "cidade": "Cajamar", "uf": "SP", "categoria": "Trail Run", "movnow_url": "https://www.movnow.com.br/eventos/411-troca-trail", "id_evento": 51200, "correspondencia": "Mesmo ID Movnow no link de inscrição/hotsite, mesma data.", "observacao": "", "snapshot": {"estado": "SP", "data_final": "2027-11-28", "nome_evento": "Troca Trail", "tipo_corrida": "rua", "ativo": true, "id_evento": 51200, "url_hotsite": "", "url_inscricao": "https://www.movnow.com.br/eventos/411-troca-trail", "tag": "2027-troca-trail", "cidade": "Cajamar", "data_inicial": "2027-11-28"}, "mensagem": "Pedido de vínculo da conta Movnow (25), registrado a pedido do administrador Leonardo Sobral (139) em 17/11/2026. Origem: conferência do catálogo público da Movnow; não representa aceite da ticketeira ou do organizador. Evento: Troca Trail; 2027-11-28; Cajamar/SP. Fonte: https://www.movnow.com.br/eventos/411-troca-trail. Correspondência: Mesmo ID Movnow no link de inscrição/hotsite, mesma data. Manter PENDENTE até análise administrativa."}]'::jsonb;
  item jsonb;
  current_event jsonb;
  affected integer;
BEGIN
  PERFORM 1 FROM tb_contas WHERE id_conta=25 AND nome_conta='Movnow' AND status::text='ATIVA' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Movnow account changed'; END IF;
  PERFORM 1 FROM tb_usuarios u LEFT JOIN tb_usuarios_gestao g ON g.id_usuario=u.id
    WHERE u.id=139 AND u.is_admin=true AND coalesce(g.ativo,true) AND NOT coalesce(g.excluido,false) FOR UPDATE OF u;
  IF NOT FOUND THEN RAISE EXCEPTION 'Requesting administrator unavailable'; END IF;
  IF jsonb_array_length(planned)<>38 THEN RAISE EXCEPTION 'Unexpected request count'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(planned) ORDER BY (value->>'id_evento')::int LOOP
    SELECT jsonb_build_object('id_evento',id_evento,'nome_evento',nome_evento,'cidade',cidade,'estado',estado,'data_inicial',data_inicial,'data_final',data_final,'tag',tag,'ativo',ativo,'url_inscricao',url_inscricao,'url_hotsite',url_hotsite,'tipo_corrida',tipo_corrida)
      INTO current_event FROM tb_evento_corridas WHERE id_evento=(item->>'id_evento')::int AND ativo=true FOR UPDATE;
    IF current_event IS DISTINCT FROM item->'snapshot' THEN RAISE EXCEPTION 'Event changed since review: %',item->>'id_evento'; END IF;
  END LOOP;
  IF EXISTS(SELECT 1 FROM tb_conta_eventos WHERE id_conta=25) OR EXISTS(SELECT 1 FROM tb_conta_evento_solicitacoes WHERE id_conta=25) THEN
    RAISE EXCEPTION 'Movnow links or requests changed since initial snapshot; refusing duplicate creation';
  END IF;
  INSERT INTO tb_conta_eventos(id_conta,id_evento,status,usuario_cadastro)
    SELECT 25,(value->>'id_evento')::int,'PENDENTE'::status_conta_evento,139 FROM jsonb_array_elements(planned);
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected<>38 THEN RAISE EXCEPTION 'Unexpected pending link count'; END IF;
  INSERT INTO tb_conta_evento_solicitacoes(id_conta,id_evento,id_usuario_solicitante,url_informada,tag_informada,mensagem,status)
    SELECT 25,(value->>'id_evento')::int,139,value->>'movnow_url',value->'snapshot'->>'tag',value->>'mensagem','PENDENTE' FROM jsonb_array_elements(planned);
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected<>38 THEN RAISE EXCEPTION 'Unexpected request count'; END IF;
  INSERT INTO tb_log(log_item,log_item_id,log_user,site,log_user_agent)
    SELECT 'solicitar_evento_conta','25,'||(value->>'id_evento'),'codex:movnow-20261117;actor=139','RH','Conferencia administrativa solicitada pelo usuario; somente pedidos PENDENTE' FROM jsonb_array_elements(planned);
  IF EXISTS(SELECT 1 FROM tb_conta_eventos WHERE id_conta=25 AND status::text<>'PENDENTE') OR
     EXISTS(SELECT 1 FROM tb_conta_evento_solicitacoes WHERE id_conta=25 AND (status<>'PENDENTE' OR data_revisao IS NOT NULL OR id_usuario_revisor IS NOT NULL))
    THEN RAISE EXCEPTION 'Unexpected approval or link state'; END IF;
END $movnow$;